public class DeprecationFilter : IResultFilter
{
    private readonly DateTime _sunsetDate = new DateTime(2026, 10, 31);

    public void OnResultExecuting(ResultExecutingContext context)
    {
        var version = context.HttpContext.GetRequestedApiVersion();
        if (version != null && version.MajorVersion == 1)
        {
            var response = context.HttpContext.Response;
            response.Headers.Deprecation = "true";
            response.Headers.Sunset = _sunsetDate.ToString("r");
            response.Headers.Append("Link",
                ", </v2/users>; rel=\"successor-version\", " +
                "</docs/migration/v1-to-v2>; rel=\"help\"");
        }
    }

    public void OnResultExecuted(ResultExecutedContext context) { }
}

// Apply globally in Program.cs:
builder.Services.AddControllers(options =>
    options.Filters.Add<DeprecationFilter>());
